# A generator specialised on queues, drains, idle and multiple keys, with 16-packet datagrams
import json, random
HEX='0123456789abcdef'
def hx(r,n): return ''.join(r.choice(HEX) for _ in range(2*n))
def gen(seed):
    r=random.Random(seed)
    cfg={'early':r.random()<0.5,'overlap':r.choice(['reject','first']),'buffer_packets':r.choice([0,1,2,3,1024]),
         'idle_ms':r.choice([0,1,2,4]),'max_streams_bidi':r.choice([0,1,4]),'max_streams_uni':r.choice([0,1,4]),
         'max_stream_data':r.choice([0,4,32]),'max_data':r.choice([0,4,100]),'crypto_limit':r.choice([0,4,64]),
         'sent':{'I':[[0,9]],'H':[[0,9]],'A':[[0,9]]}}
    events=[]; t=0
    for e in range(r.randint(3,20)):
        t+=r.choice([0,1,2,3,5])
        k=r.random()
        if k<0.35:
            events.append({'t':t,'op':'key','level':r.choice(['I','H','Z','A']),'action':r.choice(['install','discard','install','install'])})
        elif k<0.4:
            events.append({'t':t,'op':'tick'})
        else:
            size=r.choice([0,1199,1200,1300])
            npk=r.randint(1,16)
            pkts=[]
            for i in range(npk):
                lvl=r.choice(['I','H','Z','A'])
                nf=r.randint(0,3)
                frames=[{'type':r.choice(['PADDING','PING','CRYPTO','STREAM','RESET_STREAM','STOP_SENDING','ACK','CLOSE','UNKNOWN','HANDSHAKE_DONE'])} for _ in range(nf)]
                for f in frames:
                    ty=f['type']
                    if ty=='CRYPTO': f.update(offset=r.choice([0,1,5,64]),data_hex=hx(r,r.randint(0,4)))
                    elif ty=='STREAM': f.update(id=r.choice([0,4,8,1]),offset=r.choice([0,1,5]),data_hex=hx(r,r.randint(0,4)),fin=r.random()<0.5)
                    elif ty=='RESET_STREAM': f.update(id=r.choice([0,4,8,1]),final_size=r.choice([0,1,5]))
                    elif ty=='STOP_SENDING': f.update(id=r.choice([0,4,8,1]))
                    elif ty=='ACK': f.update(ranges=[[r.choice([0,1,5,9]),r.choice([0,1,5,9])] for _ in range(r.randint(0,2))])
                    elif ty=='CLOSE': f.update(app=r.random()<0.5,code=r.choice([0,7]))
                pkts.append({'level':lvl,'pn':r.choice([0,1,2,3]),'auth':r.random()<0.85,'frames':frames})
            events.append({'t':t,'op':'datagram','bytes':size,'packets':pkts})
    return {'version':1,'traces':[{'id':'q','config':cfg,'events':events}]}
import sys, subprocess, importlib.util
sys.path.insert(0,'/app/work'); import ref
spec = importlib.util.spec_from_file_location('entry','/app/submission/entry.py')
bad=0
for seed in range(2000):
    req=gen(seed)
    p=subprocess.run([sys.executable,'-I','/app/submission/entry.py'],input=json.dumps(req).encode(),capture_output=True,cwd='/app/submission')
    if p.returncode!=0: print('CRASH',seed,p.stderr.decode()[-600:]); bad+=1; break
    got=json.loads(p.stdout); exp=ref.run(req)
    if got!=exp:
        print('MISMATCH',seed); json.dump(req,open('/app/work/fail4.json','w'),indent=1); bad+=1; break
print('gen4 done bad=',bad)
EOF
